tools.schemaJson:
{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to read (relative or absolute). May end with a trailing selector such as :50-100 or :raw, address an archive member (archive.zip:inner/file), or address a SQLite database (data.db:table?limit=20)"
    },
    "offset": {
      "type": "integer",
      "description": "Line number to start reading from (1-indexed)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of lines to read"
    },
    "hashline": {
      "type": "boolean",
      "description": "Prefix each line with its line number and prepend a [path#TAG] content-hash header for anchoring hashline edit patches (default: false)"
    }
  },
  "required": [
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to write (relative or absolute)"
    },
    "content": {
      "type": "string",
      "description": "Content to write to the file"
    }
  },
  "required": [
    "path",
    "content"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to edit (relative or absolute). Required for exact-match mode; optional in hashline mode (the patch header carries its own [path#TAG])."
    },
    "oldText": {
      "type": "string",
      "description": "Exact-match mode: exact text to replace. Must occur exactly once in the file."
    },
    "newText": {
      "type": "string",
      "description": "Exact-match mode: replacement text (may be empty to delete oldText)."
    },
    "patch": {
      "type": "string",
      "description": "Hashline mode: a hashline patch — [path#TAG] section header(s) followed by SWAP/DEL/INS ops anchored on line numbers from a hashline-mode read."
    }
  }
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Directory to list (default: current directory)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of entries to return (default: 500)"
    }
  }
}

{
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "description": "The bash command to execute"
    },
    "timeout": {
      "type": "number",
      "description": "Timeout in seconds (optional, no default timeout)"
    },
    "background": {
      "type": "boolean",
      "description": "Run detached and return the job id immediately (optional, default false). Use for long-running commands."
    },
    "stdin": {
      "type": "string",
      "description": "Optional text written to the command's stdin right after start (a password/passphrase the USER supplied via the ask tool, or \"y\\n\"). Use when the command prompts for input, e.g. ssh-add or sudo. Never invent secrets — ask first."
    }
  },
  "required": [
    "command"
  ]
}

{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "status",
        "output",
        "stop"
      ],
      "description": "What to do with the job(s)"
    },
    "id": {
      "type": "string",
      "description": "The job id (e.g. sh-1); required for output/stop"
    },
    "lines": {
      "type": "number",
      "description": "Log tail size for output (default 50)"
    },
    "all": {
      "type": "boolean",
      "description": "status without id: list every exited job too"
    }
  },
  "required": [
    "action"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "diagnostics",
        "definition",
        "references",
        "rename"
      ],
      "description": "The language-server operation to run"
    },
    "path": {
      "type": "string",
      "description": "File to inspect (relative or absolute). For rename, the file containing the symbol"
    },
    "line": {
      "type": "integer",
      "description": "1-indexed line of the symbol (default 1); used by definition/references/rename"
    },
    "character": {
      "type": "integer",
      "description": "1-indexed character (column) of the symbol (default 1); used by definition/references/rename"
    },
    "newName": {
      "type": "string",
      "description": "The new identifier (required for rename)"
    }
  },
  "required": [
    "op",
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The search query"
    },
    "count": {
      "type": "integer",
      "description": "Maximum number of results to return (default: 10, max: 20)"
    },
    "site": {
      "type": "string",
      "description": "Restrict results to a single domain, e.g. 'pub.dev' (appended as a site: filter)"
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "url": {
      "type": "string",
      "description": "The absolute http(s) URL to fetch"
    }
  },
  "required": [
    "url"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "check",
        "path",
        "get",
        "set"
      ],
      "description": "The config operation to run"
    },
    "key": {
      "type": "string",
      "description": "Dotted config key for get/set (memory.projectPath, tools.web_search, provider, ...)"
    },
    "value": {
      "type": "string",
      "description": "The new value for set, rendered as a yaml scalar: true/false verbatim, numbers verbatim, lists/maps as compact JSON, strings plain or quoted"
    },
    "scope": {
      "type": "string",
      "enum": [
        "global",
        "project"
      ],
      "description": "Write scope for set. Default resolves by key: memory/cube/tools -> the project file (created minimal when absent), everything else -> the user file"
    }
  },
  "required": [
    "op"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
      "description": "The memory content — a concise, self-contained fact."
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Optional tags for categorization and retrieval."
    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
        "user"
      ],
      "description": "Where to store: project (default) or user (global)."
    }
  },
  "required": [
    "text"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "What to search for — a question, topic, or keyword."
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "limit": {
      "type": "integer",
      "description": "Max entries to return (default 20)."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The memory entry id (from memory_list/search)."
    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
        "user"
      ],
      "description": "Restrict deletion to one scope; default scans both."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
      "description": "The message to deliver when the timer fires."
    },
    "delay": {
      "type": "string",
      "description": "How long to wait: 90s / 25m / 2h / 1d (combinable, e.g. 1h30m)."
    },
    "to": {
      "type": "string",
      "description": "Recipient mailbox id; defaults to your own mailbox."
    }
  },
  "required": [
    "text",
    "delay"
  ]
}

{
  "type": "object",
  "properties": {
    "questions": {
      "type": "array",
      "description": "Questions to ask the user (at least one)",
      "items": {
        "type": "object",
        "properties": {
          "question": {
            "type": "string",
            "description": "Question text shown to the user"
          },
          "options": {
            "type": "array",
            "description": "Picker options (2-5 concise, distinct options); omit for a free-form answer",
            "items": {
              "type": "object",
              "properties": {
                "label": {
                  "type": "string",
                  "description": "Short display label"
                },
                "description": {
                  "type": "string",
                  "description": "Optional explanatory text shown with the label"
                }
              },
              "required": [
                "label"
              ]
            }
          },
          "multiSelect": {
            "type": "boolean",
            "description": "Allow multiple selections (default: false)"
          },
          "recommended": {
            "type": [
              "integer",
              "string"
            ],
            "description": "Recommended option: 0-based index or exact label; rendered as a \"Recommended\" badge"
          }
        },
        "required": [
          "question"
        ]
      }
    }
  },
  "required": [
    "questions"
  ]
}

{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Env var name to save the credential under (UPPER_SNAKE, e.g. GITHUB_TOKEN); prefilled in the user prompt"
    },
    "reason": {
      "type": "string",
      "description": "Why the credential is needed; shown to the user in the prompt"
    }
  },
  "required": [
    "name",
    "reason"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
      "description": "text prompt describing the image to generate"
    },
    "size": {
      "type": "string",
      "description": "image size, e.g. 1024x1024"
    },
    "quality": {
      "type": "string",
      "description": "image quality, e.g. standard or high"
    },
    "images": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "optional reference images (sandbox path, http(s) URL, or base64) for endpoints that accept image input"
    }
  },
  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
      "description": "text prompt describing the video to generate"
    },
    "size": {
      "type": "string",
      "description": "video size, e.g. 1920x1080"
    },
    "quality": {
      "type": "string",
      "description": "video quality, e.g. standard or high"
    },
    "images": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "optional reference images (sandbox path, http(s) URL, or base64) for endpoints that accept image input"
    }
  },
  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "model": {
      "type": "string",
      "description": "decision model slug, e.g. inception/mercury-decide:free"
    },
    "state": {
      "description": "the content the questions decide about: a string, or a JSON object/array of related context"
    },
    "questions": {
      "type": "object",
      "description": "typed questions keyed by name, e.g. {\"is_bug\": {\"type\": \"bool\", \"instructions\": \"Is this a defect?\", \"criteria\": {\"true\": \"...\", \"false\": \"...\"}}, \"team\": {\"type\": \"choice\", \"instructions\": \"Which team?\", \"criteria\": {\"frontend\": \"...\", \"payments\": \"...\"}}}"
    }
  },
  "required": [
    "model",
    "state",
    "questions"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Optional: a specific subagent id. Omit to list all."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to observe."
    },
    "tail": {
      "type": "integer",
      "description": "Number of recent messages to read (default 10)."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to message."
    },
    "message": {
      "type": "string",
      "description": "The follow-up instruction or question."
    }
  },
  "required": [
    "id",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The failed subagent id."
    },
    "message": {
      "type": "string",
      "description": "Optional resume instruction. Default: continue the original task from where the child stopped."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The background job id to abort."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "message": {
      "type": "string",
      "description": "The answer/deliverable for the parent."
    },
    "report_id": {
      "type": "string",
      "description": "Chunk protocol: the report id of the agent_message parts this reply is the final manifest for. Omit for plain replies."
    },
    "report_parts": {
      "type": "integer",
      "description": "Chunk protocol: the total number of parts the report was split into. Requires report_id."
    }
  },
  "required": [
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "type": "string",
      "description": "The sibling subagent id, \"main\", an absolute mailbox \"<sessionId>/main\", a session name from agent_directory, or \"name@machine\" for a cross-machine peer (A2A gateway)."
    },
    "message": {
      "type": "string",
      "description": "The message body for the sibling."
    },
    "report_id": {
      "type": "string",
      "description": "Chunk protocol: the child-selected report id this message is a part of. Same-session recipients only."
    },
    "part_index": {
      "type": "integer",
      "description": "Chunk protocol: the 0-based index of this part. Parts must arrive in order (0, 1, 2, …) without duplicates; the final reply manifest is validated against what the harness observed. Requires report_id."
    },
    "wake": {
      "type": "boolean",
      "description": "When the cross-session target is asleep (no live watcher — it would not read the message until started), launch a detached headless run of its session to process the inbox now. Default: true. The run appends to the same session JSONL, so a later interactive start resumes it."
    }
  },
  "required": [
    "to",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "all": {
      "type": "boolean",
      "description": "Include stale mailboxes (no recent activity, nothing pending). Default: false."
    }
  }
}

{
  "type": "object",
  "properties": {
    "context": {
      "type": "string",
      "description": "Shared background (project state, constraints, contracts) rendered into every spawned subagent's system prompt"
    },
    "tasks": {
      "type": "array",
      "description": "One subagent per item",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Stable id base ([A-Za-z0-9_-]); uniquified per session"
          },
          "agent": {
            "type": "string",
            "description": "Agent type for this item (see the tool description); omit for the general-purpose worker"
          },
          "task": {
            "type": "string",
            "description": "Complete, self-contained instructions for the subagent"
          },
          "outputSchema": {
            "description": "JSON Schema the subagent's final output must satisfy; invalid output gets one fix retry, then the item fails"
          }
        },
        "required": [
          "task"
        ]
      }
    },
    "background": {
      "type": "boolean",
      "description": "Run items as background jobs and return job ids immediately (default: host configuration)"
    }
  },
  "required": [
    "context",
    "tasks"
  ]
}

{
  "type": "object",
  "properties": {
    "goal": {
      "type": "string",
      "description": "Investigation goal for this checkpoint"
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Investigation findings retained after the rewind"
    }
  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
      "description": "Numeric id or range from a context marker, e.g. \"5\" or \"2-6\". Omit to list the hidden-segment index."
    },
    "action": {
      "type": "string",
      "description": "Tier 2 segment management (issue #1379). With a target: \"hide\" folds a dead-weight segment into its expandable marker right now, without waiting for pressure; \"pin\" shields a segment from every hide/compact path; \"unpin\" releases it. Omit to expand the target."
    },
    "query": {
      "type": "string",
      "description": "Search the hidden segments (preview and full content) when you know WHAT you need but not the id. Free — no budget."
    },
    "page": {
      "type": "integer",
      "description": "1-based page for giant segments (default 1)",
      "minimum": 1
    }
  },
  "required": []
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

content.text:
# AI Teammate — thin stub over the factory home (dmtools-agentic-workflows),
# SELF-HOSTED ENGINE: this repo IS the dmtools-agents engine, so factory_ref
# rides the triggering commit — the factory always executes the exact tree
# under development.
#
# ALL logic lives in IstiN/dmtools-agentic-workflows/.github/workflows/
# factory-teammate.yml (guard, legs, verdict, sessions, memory). This file
# carries the repository event triggers + the call only.
#
# Gate: the loop starts when a human ASSIGNS an issue to `ai-teammate`.
# Secrets via `secrets: inherit`: SOURCE_GITHUB_TOKEN (present), plus
# ZAI_CODE_KEY / KIMI_REVIEW_KEY when the fa/zai runners are used.
#
# gh-676 (2026-10-03): while this file was unparseable (#669 residue —
# duplicate permission keys, fixed in #671), GitHub kept a stale push-event
# registration: every machine-sm state-publish push to `factory-data`
# spawned an instant-fail event=push run with zero jobs ("the phantom").
# This comment block is the standard cure — a no-op touch of the file: the
# default-branch blob change forces GitHub to re-index the registration
# from the real triggers below. There is NO push trigger by design; the
# trigger set (issues + workflow_dispatch only) and the duplicate-key
# ban are guarded by js/unit-tests/test_workflowLint.js.
#
# gh-1076 (live 2026-10-19, #1074): ONE owner assign spawned THREE runs —
# the `assigned` event plus two `labeled` events from dmtools-factory-
# bot's OWN consequence labels. `types: [assigned, labeled]` fired on
# EVERY label write, so the workflow re-triggered itself on its own
# status:* consequences; gh-1065 dedup made the duplicates self-skip, but
# each still started a run, occupied the concurrency group, spammed the
# run list and cost a probe. GitHub cannot filter label names in `on:`,
# and a job-level `if:` still starts and LISTS the run (the owner's
# explicit complaint) — so the event trigger is `assigned` ONLY.
# Label-driven pickup (arming labels agent:*) continues through the SM
# tick's workflow_dispatch path (gh-1028 dedup), the governed lane.
name: AI Teammate

# gh-1065: the title carries the LEG for every path — the dispatch input
# leg directly, and for event-path runs the strongest arming label on the
# issue (rework > review > pr_approved → review > dev). legOfRunName
# (js/common/teammateEventDedup.js) parses the trailing token, so a
# COMPLETED owner stays title-precise: the strict completed-owner leg rule
# (a leg-less completed run never swallows a KNOWN new leg) can only work
# when real leg runs carry their leg in the title.
# gh-1076: the trailing `|| github.event.label.name` fallback is gone with
# the labeled trigger — labeled events can no longer start this workflow,
# and assigned/dispatch events resolve their leg from the labels above.
# gh-1075: a PR-anchored dispatch ALSO carries the `· pr-<N>` anchor right
# after the issue slot, BEFORE the leg — the gh-1075 fork path always
# backfills inputs.pr, and the SM's pull-keyed leg probe
# (branchLegGuard.hasActiveLegRunForPull) keys on this whole-token anchor
# to suppress a second rework arm on the same fork PR. The anchor sits
# BEFORE the trailing-leg token on purpose: stubTailLegOf (the teammate:
# title family in legOfRunName) parses the leg at the END of the title,
# and the gh-1065 completed-owner leg precision depends on it.
run-name: "teammate: ${{ github.event_name }} #${{ github.event.issue.number || github.event.inputs.issue }}${{ (github.event.inputs.pr || '') != '' && format(' · pr-{0}', github.event.inputs.pr) || '' }} ${{ github.event.inputs.leg || (contains(github.event.issue.labels.*.name, 'agent:rework') && 'rework') || (contains(github.event.issue.labels.*.name, 'agent:review') && 'review') || (contains(github.event.issue.labels.*.name, 'pr_approved') && 'review') || (contains(github.event.issue.labels.*.name, 'agent:dev') && 'dev') || (contains(github.event.issue.labels.*.name, 'agent:develop') && 'dev') }}"

on:
  # gh-1076: `assigned` ONLY — see the header. The labeled trigger used to
  # re-fire this workflow on the factory's own consequence labels.
  issues:
    types: [assigned]
  workflow_dispatch:
    inputs:
      issue:
        description: 'Issue number (for dispatch runs)'
        type: string
      leg:
        description: 'Which leg to run'
        type: choice
        # gh-1352: polish — the bounded suggestion-only lap the disposition
        # loop dispatches on an approved BLOCKED head (top-K threads,
        # once-per-head, instability-budgeted).
        # gh-1366: analyze — the AI failure-analyzer leg the SM dispatches
        # when a same-signature failure streak crosses
        # failureAnalysis.afterFailures (transient vs deterministic-infra).
        # analyze: requires the factory leg (gh-1366) — no-op until it ships.
        options: [dev, review, rework, polish, analyze]
      reason:
        description: 'Why (audit trail)'
        type: string
      pr:
        description: 'PR number for PR-anchored runs (review leg on PRs born without an issue, #687)'
        required: false
        type: string
        default: ''
      checkout_ref:
        description: 'gh-1075/gh-1096: refs/pull/<N>/head for fork-PR legs (empty = dispatch ref)'
        required: false
        type: string
        default: ''

permissions:
  # The factory (factory-teammate.yml@e611e5f) requests this set and a
  # reusable workflow cannot RAISE rights above its caller — the stub must
  # grant the ceiling or every dispatch startup-fails (live dmtools-agents
  # 2026-10-03: 'requesting actions: write, contents: write, issues: write,
  # pull-requests: write, but is only allowed contents: read' — the issue-
  # driven dev lane never ran in this repo).
  actions: write
  contents: write
  issues: write
  pull-requests: write

concurrency:
  group: ai-teammate-${{ github.event.issue.number || github.event.inputs.issue || (github.event.inputs.pr && format('pr-{0}', github.event.inputs.pr)) || github.run_id }}
  cancel-in-progress: false

jobs:
  # gh-1065 (live 2026-10-18, issues #1040–#1043 / #1061): one human action
  # (assign, or assign-while-labels-change) emits MULTIPLE issues events and
  # each event started its own run — two per issue, three on #1061, the
  # owner hand-cancelling duplicates. The gh-1028 dedup guards the SM
  # dispatch path only; this job is the missing event-path gate. It probes
  # the repo's ai-teammate.yml runs (per-status gh api fan-out, smAgent
  # parity) and lets the `teammate` call fire only when no OLDER run for
  # the same issue + leg is in flight or freshly completed. Probe errors
  # FAIL OPEN (AC3): a broken check writes proceed=true so the only trigger
  # of a burst is never silently swallowed. The decision itself is the
  # unit-tested pure module js/common/teammateEventDedup.js (AC4) — this
  # step is transport only. The probe short-circuits BEFORE any API call
  # for workflow_dispatch (SM-side gh-1028 governs it) and non-teammate
  # assignees. gh-1076: with the `labeled` trigger removed, the labeled
  # preflight went with it — labeled events can no longer reach this job.
  dedup:
    name: Event-path dedup probe (gh-1065)
    runs-on: ubuntu-latest
    # gh-1065 rework (review thread — gh-1029 zero-burn parity): this gate
    # MIRRORS the teammate call gate below. Rejected events execute ZERO
    # jobs: the run concludes failure (the gh-676 phantom pattern) and —
    # because only conclusion 'success' owns the freshness window — can
    # never suppress a trigger for an issue whose leg never ran.
    # gh-1076: the `labeled` trigger is gone (the gate's labeled mirror
    # branch went with it), so the remaining event path is `assigned`
    # addressed to ai-teammate; the dispatch path skips the probe by
    # preflight below.
    if: >-
      github.event_name == 'workflow_dispatch' ||
      (github.event_name == 'issues' &&
       github.event.action == 'assigned' &&
       contains(github.event.issue.assignees.*.login, 'ai-teammate'))
    outputs:
      proceed: ${{ steps.probe.outputs.proceed }}
      audit: ${{ steps.probe.outputs.audit }}
    steps:
      - uses: actions/checkout@v4
      - id: probe
        name: Decide whether this event duplicates an in-flight teammate run
        env:
          GH_TOKEN: ${{ github.token }}
          REPO: ${{ github.repository }}
          EVENT_NAME: ${{ github.event_name }}
          ACTION: ${{ github.event.action }}
          ISSUE_LABELS: ${{ toJson(github.event.issue.labels.*.name) }}
          ISSUE: ${{ github.event.issue.number || github.event.inputs.issue }}
          INPUT_PR: ${{ github.event.inputs.pr || '' }}
          INPUT_LEG: ${{ github.event.inputs.leg || '' }}
          ASSIGNEES: ${{ toJson(github.event.issue.assignees.*.login) }}
          SELF_ID: ${{ github.run_id }}
          SELF_RUN_NUMBER: ${{ github.run_number }}
          WORKFLOW_FILE: ai-teammate.yml
          # GITHUB_OUTPUT is provided by the runner — do NOT set it here.
        run: |
          node <<'DEDUP_PROBE_EOF'
          const { execFileSync } = require('child_process');
          const fs = require('fs');
          const dedup = require('./js/common/teammateEventDedup.js');

          const env = process.env;
          // gh-1065 rework (review thread): label/login names may contain
          // spaces — the lists ride as JSON. Fallback: the legacy
          // space-joined shape still parses (defense in depth).
          const parseEventList = (raw) => {
            try {
              const v = JSON.parse(raw || '[]');
              if (Array.isArray(v)) return v.filter(Boolean);
            } catch (e) { /* legacy space-joined list — fall through */ }
            return (raw || '').split(' ').filter(Boolean);
          };
          const issueLabels = parseEventList(env.ISSUE_LABELS);
          const assignees = parseEventList(env.ASSIGNEES);

          const out = (proceed, audit) => {
            const line = String(audit).replace(/\s+/g, ' ').trim();
            fs.appendFileSync(env.GITHUB_OUTPUT || '/dev/null',
              `proceed=${proceed}\naudit=${line}\n`);
            console.log((proceed ? '::notice::' : '::warning::') + line);
          };

          try {
            // gh-1076: the `labeled` trigger is gone — `labeled` never
            // reaches this probe. Skip the probe entirely (no API burn)
            // for assigns not addressed to ai-teammate (the job gate
            // rejects them; zero jobs execute). gh-1153: workflow_dispatch
            // ALSO runs decideEventDedup against older in-flight runs for
            // the same issue or PR anchor + leg.
            let preflight = null;
            if (env.EVENT_NAME === 'issues' && env.ACTION === 'assigned' && assignees.indexOf('ai-teammate') === -1) {
              preflight = 'not assigned to ai-teammate: the teammate gate rejects it; no probe spent';
            }
            if (preflight) {
              out(true, 'teammate dedup (gh-1065): ' + preflight + '; proceeding');
              process.exit(0);
            }

            // Per-status fan-out (smAgent parity): the four active states plus
            // 'completed' (the freshness window needs recently-settled runs —
            // burst duplicates reach this probe only after the concurrency
            // group releases the first run). Each status is best-effort: a
            // failing status is logged and skipped — if EVERY status failed,
            // the run list is empty and the decision fails open by design.
            const statuses = ['queued', 'in_progress', 'waiting', 'pending', 'completed'];
            let runs = [];
            let probeErrors = 0;
            for (const status of statuses) {
              try {
                const raw = execFileSync('gh', [
                  'api', `repos/${env.REPO}/actions/workflows/${env.WORKFLOW_FILE}/runs`,
                  '-X', 'GET', '-f', `status=${status}`, '-f', 'per_page=50',
                  '--jq', '.workflow_runs[] | {id, run_number, name, status, conclusion, created_at, updated_at, path}'
                ], { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 });
                const batch = raw.trim() ? raw.trim().split('\n').filter(Boolean)
                  .map((l) => { try { return JSON.parse(l); } catch (e) { return null; } })
                  .filter(Boolean) : [];
                runs = runs.concat(batch);
              } catch (e) {
                probeErrors++;
                console.log(`::notice::teammate dedup (gh-1065): ${status} probe failed (${(e.message || e).toString().slice(0, 120)}) — status skipped, fail-open`);
              }
            }

            const verdict = dedup.decideEventDedup({
              eventName: env.EVENT_NAME,
              action: env.ACTION,
              labelName: undefined, // gh-1076: no labeled trigger — only assigned/dispatch reach the probe
              issueLabelNames: issueLabels,
              issue: parseInt(env.ISSUE, 10),
              pr: parseInt(env.INPUT_PR, 10),
              leg: env.INPUT_LEG,
              workflowFile: env.WORKFLOW_FILE,
              runs: runs,
              // The run_number tie-break needs no clock on the self side:
              // REST always carries run_number for every run. The freshness
              // window DOES need a clock — without nowMs the module degrades
              // to in-flight-only and a completed burst owner would never
              // suppress (transport regression caught by the mocked-gh
              // smoke).
              nowMs: Date.now(),
              selfRun: {
                id: parseInt(env.SELF_ID, 10),
                runNumber: parseInt(env.SELF_RUN_NUMBER, 10)
              }
            });
            const suffix = probeErrors > 0 && verdict.proceed
              ? ` (${probeErrors}/${statuses.length} probe statuses failed — degraded, fail-open)` : '';
            out(verdict.proceed, verdict.audit + suffix);
          } catch (e) {
            // AC3 fail-open, catch-all: an unexpected probe crash must never
            // fail the job (that would wedge the dispatch path behind needs:)
            // and must never swallow the only trigger — proceed with an audit.
            out(true, 'teammate dedup (gh-1065): probe degraded — fail-open (' +
              (e && e.message ? e.message : e) + '); proceeding so the only trigger is never swallowed');
          }
          DEDUP_PROBE_EOF

  teammate:
    # gh-1076: the `labeled` trigger is GONE — this workflow used to
    # re-fire on its own consequence labels (live #1074: 3 runs for one
    # assign). Label-driven pickup (arming labels agent:*) now comes ONLY
    # through the SM tick's workflow_dispatch (gh-1028 dedup). The
    # remaining event path is `assigned`, still keyed to the ai-teammate
    # assignee — the gh-1029 origin: the old assignee-only clause matched
    # ANY labeled event on an assigned issue, so each leg re-triggered a
    # guaranteed no-op run (run 39111715487 → 39111765329 on #1027,
    # 2026-10-18). The gate has keyed the action ever since; gh-1076 made
    # the labeled branch unreachable and it was removed.
    #
    # gh-1065: the call additionally needs the event-path dedup probe
    # (needs.dedup) — the probe outputs proceed=true unconditionally for
    # the dispatch path, so workflow_dispatch behaviour is unchanged.
    needs: dedup
    if: >-
      needs.dedup.outputs.proceed == 'true' &&
      (github.event_name == 'workflow_dispatch' ||
       (github.event_name == 'issues' &&
        github.event.action == 'assigned' &&
        contains(github.event.issue.assignees.*.login, 'ai-teammate')))
    uses: IstiN/dmtools-agentic-workflows/.github/workflows/factory-teammate.yml@main
    with:
      issue: ${{ github.event.issue.number || github.event.inputs.issue }}
      pr: ${{ github.event.inputs.pr || '' }}
      # gh-1096: requires the factory-teammate.yml checkout_ref input (awf PR merged first).
      checkout_ref: ${{ github.event.inputs.checkout_ref || '' }}
      machine-author: 'ai-teammate'
      leg: ${{ github.event.inputs.leg || '' }}
      reason: ${{ github.event.inputs.reason || github.event_name }}
      flutter-version: ''  # JS/configs repo — dmtools & fa CLIs are prebuilt; no Flutter toolchain needed
      # 2026-10-17 incident: GitHub's ubuntu-slim SKU started force-cancelling
      # teammate jobs at exactly ~15m24s (6/6 legs tonight, 15:20–15:26;
      # "The operation was canceled" from the control plane, conclusion=cancelled).
      # Yesterday the same SKU ran legs for 24 min fine. dmtools-dart legs on
      # ubuntu-24.04 are unaffected. Owner decision: CI checks stay on slim,
      # ai-teammate legs move to ubuntu-latest until slim is healthy again.
      runner: 'ubuntu-latest'
    secrets: inherit

# AI Teammate — GitHub-issues machine runner (TEMPLATE).
#
# Copy into the TARGET repository (.github/workflows/ai-teammate.yml) and
# adapt the RUNNER_* entries. This is the trimmed generic variant of the
# battle-tested machine-kit workflow (see epam/dmtools-dart
# .github/workflows/ai-teammate.yml for the full reference with comments).
#
# Two entry paths, and BOTH must survive for the loop to be self-healing:
#   1. issues: [assigned, labeled] — the fast path (labels added with a
#      real PAT fire events; GITHUB_TOKEN-added labels do NOT — that is
#      exactly what the SM cron covers)
#   2. workflow_dispatch (issue / leg / reason) — the SM dispatch path:
#      the reconciler fires this directly, so mute labels cannot stall the
#      loop
#
# The guard derives the leg: dispatch input leg > label agent:rework >
# label agent:review > assignee/agent:dev (dev). Each leg runs the dmtools
# agent config named by RUNNER_*: dev (story/bug) develops from the issue
# body, review produces a machine PR review verdict, rework fixes the
# linked PR by the review threads.
#
# gh-1065/gh-1073: issues events are deduped before the leg fires — one
# human action (assign, or assign-while-labels-change) emits MULTIPLE
# issues events, and without the `dedup` probe job each event spawned its
# own teammate run (live 2026-10-18: #1040–#1043 two runs each, #1061
# three). The probe is transport only; the decision is the unit-tested
# pure module js/common/teammateEventDedup.js, shipped in the agents pack
# the runner leg mounts (dmtools-agents checkout). The probe FAILS OPEN on
# errors, so a broken check never swallows the only trigger.
name: 'AI Teammate'

# Run title carries the EFFECTIVE anchor (owner 2026-09-27, live: dmd run
# 36333172145): a PR-anchored SM dispatch (#544/#687 — inputs.pr set,
# inputs.issue empty) must title '▶ rework (SM) · pr-266', never the
# malformed '▶ rework (SM) · gh- · gh-: '. (inputs.pr || '') guards the
# label-event path, where inputs are null — null != '' would be TRUE and
# render 'pr-' for ordinary issue events.
#
# gh-1065/gh-1073: the issues-event title ALSO carries the LEG — the
# strongest arming label on the issue (rework > review > pr_approved →
# review > dev), not the label written by THIS event: assign-while-labels-
# change emits a bare `assigned` event whose github.event.label.name is
# empty. legOfRunName (js/common/teammateEventDedup.js) parses this emoji
# title family, so a COMPLETED owner stays title-precise: the strict
# completed-owner leg rule (a leg-less completed run never swallows a
# KNOWN new leg) can only work when real leg runs carry their leg here.
run-name: >-
  ${{ github.event_name == 'workflow_dispatch' &&
      format('▶ {0} (SM) · {1}', github.event.inputs.leg,
        (github.event.inputs.pr || '') != '' && format('pr-{0}', github.event.inputs.pr)
        || format('gh-{0}', github.event.inputs.issue)) ||
      (contains(github.event.issue.labels.*.name, 'agent:rework') && '🔧 rework') ||
      (contains(github.event.issue.labels.*.name, 'agent:review') && '🔍 review') ||
      (contains(github.event.issue.labels.*.name, 'pr_approved') && '🔍 review') ||
      (contains(github.event.issue.labels.*.name, 'agent:dev') && '⚒️ dev') ||
      (contains(github.event.issue.labels.*.name, 'agent:develop') && '⚒️ dev') ||
      github.event.label.name || '⚒️ dev' }}
  · ${{ (github.event.inputs.pr || '') != '' && format('pr-{0}', github.event.inputs.pr)
      || format('gh-{0}', github.event.issue.number || github.event.inputs.issue) }}${{
      github.event.issue.title && format(': {0}', github.event.issue.title) || '' }}

on:
  issues:
    types: [assigned, labeled]
  workflow_dispatch:
    inputs:
      issue:
        description: 'Issue number to run the agent on (empty for PR-anchored runs, #687)'
        required: false
        type: string
        default: ''
      leg:
        description: 'Which leg to run'
        required: true
        type: choice
        # gh-1352: polish — the bounded suggestion-only lap the disposition
        # loop dispatches on an approved BLOCKED head (top-K threads,
        # once-per-head, instability-budgeted). Backfilled from the live
        # workflow so the choice sets cannot drift.
        # gh-1366: analyze — the AI failure-analyzer leg the machine SM
        # dispatches when a same-signature failure streak crosses
        # failureAnalysis.afterFailures (transient vs deterministic-infra).
        # analyze: requires the factory leg (gh-1366) — no-op until it ships.
        options: [dev, review, rework, polish, analyze]
      reason:
        description: 'Why this dispatch (audit trail, shown in logs)'
        required: false
        type: string
      pr:
        description: 'PR number for PR-anchored runs (#544/#687) — the SM dispatches review/rework with pr instead of issue when the PR has no resolvable LOCAL issue; gh-1075 fork-PR dispatches always backfill it so the run title carries the · pr-<N> anchor'
        required: false
        type: string
        default: ''
      checkout_ref:
        description: 'gh-1075 fork-PR dispatch: the leg checks out this ref (refs/pull/<N>/head — always fetchable on the base repo, even when the fork branch is deleted) instead of the dispatch ref. DECLARED here because GitHub 422s undeclared dispatch inputs ("Unexpected inputs provided"); consumption (checkout step + fork push-back) is tracked in #1096 — the gh-1075 review confirmed #1074 is observability-only and does not own checkout behavior.'
        required: false
        type: string
        default: ''

concurrency:
  # PR-anchored dispatches (#544/#687) carry no issue — fall back to the pr
  # input so each PR keeps its OWN group ('ai-teammate-issue-pr-266');
  # without it every PR-anchored run shares the empty group and serializes
  # across unrelated PRs.
  group: ai-teammate-issue-${{ github.event.issue.number || github.event.inputs.issue || format('pr-{0}', github.event.inputs.pr) }}
  cancel-in-progress: false

permissions:
  contents: write
  pull-requests: write
  issues: write
  actions: write

env:
  AGENT_HANDLE: ai-teammate
  # ── adapt per target repo ───────────────────────────────────────────────
  RUNNER_STORY: dmtools-agents/story_development.json
  RUNNER_BUG: dmtools-agents/bug_development.json
  RUNNER_REVIEW: dmtools-agents/pr_review.json
  RUNNER_REWORK: dmtools-agents/pr_rework.json
  DMTOOLS_AGENTS_REF: main
  DMTOOLS_VERSION: v0.1.5
  FA_VERSION: latest
  # ─────────────────────────────────────────────────────────────────────────
  # Secrets expected: SOURCE_GITHUB_TOKEN (PAT), plus the AI provider key
  # referenced by the runner configs (e.g. ZAI_CODE_KEY / KIMI_REVIEW_KEY).

jobs:
  guard:
    # gh-1029: the `labeled` trigger fires on EVERY label write — including
    # the leg's own lifecycle labels (status:*, ai_developed, ...) — and
    # `on:` cannot filter by label name. Without this job-level gate the
    # guard allocated a runner on each lifecycle-label write only to decide
    # run=false (the self-retrigger no-op burn). `assigned` and the arming
    # `labeled` events (agent:*) still enter; lifecycle labels skip the job
    # entirely and never allocate a runner.
    if: >-
      github.event_name == 'workflow_dispatch' ||
      (github.event_name == 'issues' &&
       github.event.action == 'assigned') ||
      (github.event_name == 'issues' &&
       github.event.action == 'labeled' &&
       (github.event.label.name == 'agent:dev' ||
        github.event.label.name == 'agent:develop' ||
        github.event.label.name == 'agent:review' ||
        github.event.label.name == 'agent:rework' ||
        github.event.label.name == 'pr_approved'))
    runs-on: ubuntu-latest
    outputs:
      run: ${{ steps.check.outputs.run }}
      runner: ${{ steps.check.outputs.runner }}
      kind: ${{ steps.check.outputs.kind }}
    steps:
      - name: Decide whether this event is for the agent
        id: check
        env:
          GH_TOKEN: ${{ github.token }}
          NUMBER: ${{ github.event.issue.number || github.event.inputs.issue }}
          ASSIGNEES: ${{ join(github.event.issue.assignees.*.login, ' ') }}
          LABELS: ${{ join(github.event.issue.labels.*.name, ' ') }}
          INPUT_LEG: ${{ github.event.inputs.leg }}
        run: |
          if [ -n "$INPUT_LEG" ]; then
            LABELS="$(gh issue view "$NUMBER" --repo "$GITHUB_REPOSITORY" --json labels -q '[.labels[].name] | join(" ")')"
            ASSIGNEES="$(gh issue view "$NUMBER" --repo "$GITHUB_REPOSITORY" --json assignees -q '[.assignees[].login] | join(" ")')"
          fi
          state="$(gh issue view "$NUMBER" --repo "$GITHUB_REPOSITORY" --json state -q .state)"
          if [ "$state" != "OPEN" ]; then
            echo "run=false" >> "$GITHUB_OUTPUT"; exit 0
          fi
          if echo "$LABELS" | grep -qw "agent:skip"; then
            echo "run=false" >> "$GITHUB_OUTPUT"; exit 0
          fi
          runner=""
          if [ "$INPUT_LEG" = "rework" ]; then runner="$RUNNER_REWORK";
          elif [ "$INPUT_LEG" = "review" ]; then runner="$RUNNER_REVIEW";
          elif [ "$INPUT_LEG" = "dev" ]; then
            title="$(gh issue view "$NUMBER" --repo "$GITHUB_REPOSITORY" --json title -q .title)"
            if echo "$title" | grep -qiE '^\[?bug\]' || echo "$LABELS" | grep -qwi "bug"; then
              runner="$RUNNER_BUG"
            else
              runner="$RUNNER_STORY"
            fi
          elif echo "$LABELS" | grep -qw "agent:rework"; then runner="$RUNNER_REWORK";
          elif echo "$LABELS" | grep -qw "agent:review"; then runner="$RUNNER_REVIEW";
          elif echo "$ASSIGNEES" | grep -qw "$AGENT_HANDLE" || echo "$LABELS" | grep -qw "agent:dev"; then
            title="$(gh issue view "$NUMBER" --repo "$GITHUB_REPOSITORY" --json title -q .title)"
            if echo "$title" | grep -qiE '^\[?bug\]' || echo "$LABELS" | grep -qwi "bug"; then
              runner="$RUNNER_BUG"
            else
              runner="$RUNNER_STORY"
            fi
          fi
          if [ -n "$runner" ]; then
            echo "run=true" >> "$GITHUB_OUTPUT"
            echo "runner=$runner" >> "$GITHUB_OUTPUT"
            echo "kind=$(echo "$runner" | grep -q review && echo review || (echo "$runner" | grep -q rework && echo rework || echo dev))" >> "$GITHUB_OUTPUT"
          else
            echo "run=false" >> "$GITHUB_OUTPUT"
          fi

  # gh-1065/gh-1073: event-path dedup probe (the engine repo's stub carries
  # the same job — see .github/workflows/ai-teammate.yml). One human action
  # (assign, or assign-while-labels-change) emits MULTIPLE issues events and
  # each event started its own teammate run — two per issue, three on #1061,
  # the owner hand-cancelling duplicates. The gh-1028 dedup guards the SM
  # dispatch path only; this job is the missing event-path gate. It probes
  # the repo's ai-teammate.yml runs (per-status gh api fan-out, smAgent
  # parity) and lets the `teammate` call fire only when no OLDER run for
  # the same issue + leg is in flight or freshly completed. Probe errors
  # FAIL OPEN (AC3): a broken check writes proceed=true so the only trigger
  # of a burst is never silently swallowed. The decision itself is the
  # unit-tested pure module js/common/teammateEventDedup.js (AC4) — this
  # step is transport only. The probe short-circuits BEFORE any API call
  # for workflow_dispatch (SM-side gh-1028 governs it), non-arming
  # lifecycle labels and non-teammate assignees.
  dedup:
    name: Event-path dedup probe (gh-1065)
    runs-on: ubuntu-latest
    # gh-1029 zero-burn parity: this gate MIRRORS the guard gate above.
    # `on:` fires on EVERY label write repo-wide, and an unguarded dedup
    # job would allocate a runner (pack checkout + node boot) per
    # lifecycle-label storm — the exact burn gh-1029 eliminated. Rejected
    # events execute ZERO jobs: the run concludes failure (the gh-676
    # phantom pattern) and — because only conclusion 'success' owns the
    # freshness window — can never suppress a trigger for an issue whose
    # leg never ran. NOTE: a job-level `if:` cannot read the env block —
    # if you retarget AGENT_HANDLE below, mirror it into the two
    # 'ai-teammate' literals in this gate and the teammate call gate.
    if: >-
      github.event_name == 'workflow_dispatch' ||
      (github.event_name == 'issues' &&
       github.event.action == 'assigned' &&
       contains(github.event.issue.assignees.*.login, 'ai-teammate')) ||
      (github.event_name == 'issues' &&
       github.event.action == 'labeled' &&
       (github.event.label.name == 'agent:dev' ||
        github.event.label.name == 'agent:develop' ||
        github.event.label.name == 'agent:review' ||
        github.event.label.name == 'agent:rework' ||
        github.event.label.name == 'pr_approved'))
    outputs:
      proceed: ${{ steps.probe.outputs.proceed }}
      audit: ${{ steps.probe.outputs.audit }}
    steps:
      # The pure decision module ships in the agents pack (the runner leg
      # below mounts the same checkout) — the consumer repo tree does NOT
      # carry js/common/. Same DMTOOLS_AGENTS_REF pin as the runner leg.
      - name: Checkout dmtools-agents (dedup decision module)
        uses: actions/checkout@v4
        with:
          repository: IstiN/dmtools-agents
          ref: ${{ env.DMTOOLS_AGENTS_REF }}
          path: dmtools-agents
      - id: probe
        name: Decide whether this event duplicates an in-flight teammate run
        env:
          GH_TOKEN: ${{ github.token }}
          REPO: ${{ github.repository }}
          EVENT_NAME: ${{ github.event_name }}
          ACTION: ${{ github.event.action }}
          LABEL_NAME: ${{ github.event.label.name }}
          ISSUE_LABELS: ${{ toJson(github.event.issue.labels.*.name) }}
          ISSUE: ${{ github.event.issue.number || github.event.inputs.issue }}
          INPUT_PR: ${{ github.event.inputs.pr || '' }}
          INPUT_LEG: ${{ github.event.inputs.leg || '' }}
          ASSIGNEES: ${{ toJson(github.event.issue.assignees.*.login) }}
          SELF_ID: ${{ github.run_id }}
          SELF_RUN_NUMBER: ${{ github.run_number }}
          WORKFLOW_FILE: ai-teammate.yml
          # GITHUB_OUTPUT is provided by the runner — do NOT set it here.
        run: |
          node <<'DEDUP_PROBE_EOF'
          const { execFileSync } = require('child_process');
          const fs = require('fs');
          const dedup = require('./dmtools-agents/js/common/teammateEventDedup.js');

          const env = process.env;
          // gh-1065 rework (review thread): label/login names may contain
          // spaces — the lists ride as JSON. Fallback: the legacy
          // space-joined shape still parses (defense in depth).
          const parseEventList = (raw) => {
            try {
              const v = JSON.parse(raw || '[]');
              if (Array.isArray(v)) return v.filter(Boolean);
