function buildFactorySetup() {
  const stamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14); // YYYYMMDDHHMMSS
  mkdirSync(OUT_DIR, { recursive: true });
  const zipPath = resolve(OUT_DIR, `factory-setup-${stamp}.zip`);
  const staging = mkdtempSync(join(tmpdir(), 'factory-setup-'));
  try {
    mkdirSync(join(staging, 'configs'), { recursive: true });
    cpSync(join(ROOT, 'setup'), join(staging, 'setup'), { recursive: true });
    mkdirSync(join(staging, 'scripts'), { recursive: true });
    // Engine-side factory scripts (awf de-bloat 2026-10-16): these carry SM
    // cycle logic, not factory-bootstrap glue — they belong to the engine
    // pack. Keep this list in sync with awf's call sites.
    for (const engineScript of FACTORY_SETUP_SCRIPTS) {
      const dest = join(staging, 'scripts', engineScript);
      copyFileSync(join(ROOT, 'scripts', engineScript), dest);
      chmodSync(dest, 0o755);
    }
    // gh-1363: the leg-failure builder closure the notice script requires.
    mkdirSync(join(staging, 'js', 'common'), { recursive: true });
    for (const jsFile of FACTORY_SETUP_JS) {
      copyFileSync(join(ROOT, jsFile), join(staging, jsFile));
    }
    for (const leg of FACTORY_SETUP_LEGS) {
      copyFileSync(join(ROOT, `${leg}.json`), join(staging, 'configs', `${leg}.json`));
    }
    // Plain integrity inventory (not a dmtools agent-pack manifest — this is
    // workflow glue, never resolved by the agent pack registry).
    const sums = [];
    for (const f of listFilesRecursive(staging)) {
      sums.push(`${createHash('sha256').update(readFileSync(f.absPath)).digest('hex')}  ${f.relPath}`);
    }

